import{_ as r,l as o,o as e,c as d,v as s,p as i,x as n,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"指向分析 Andersen / Steensgaard","description":"","frontmatter":{"title":"指向分析 Andersen / Steensgaard","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/points-to-analysis.md","filePath":"cs/points-to-analysis.md","lastUpdated":1789023840000}'),A={name:"cs/points-to-analysis.md"};function h(m,a,S,_,u,g){const t=o("Mermaid");return e(),d("div",null,[a[1]||(a[1]=s('<h1 id="指向分析-andersen-steensgaard" tabindex="-1">指向分析 Andersen / Steensgaard <a class="header-anchor" href="#指向分析-andersen-steensgaard" aria-label="Permalink to &quot;指向分析 Andersen / Steensgaard&quot;">​</a></h1><div class="epigraph"><p>Andersen 把赋值当子集约束，精确、偏立方；Steensgaard 用并查集把指针等同，近线性、更粗。二者都给出每个指针的指向集。</p><footer>—— 据 Andersen, Program Analysis and Specialization, 1994；Steensgaard, Points-to Analysis in Almost Linear Time, 1996 整理</footer></div><p>上一课<a href="/cs/alias-analysis">别名分析</a>要指向集才能回答 May。缺口是<strong>怎么算指向</strong>：<code>p=&amp;x</code>、<code>p=q</code>、<code>*p=q</code>、<code>p=*q</code>。Andersen：包含约束，解得较小集合。Steensgaard：等式，快。本课钉约束形态，不写全部流敏感变体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流不敏感、上下文不敏感是基线：每个变量一个指向集，忽略顺序。<code>p=&amp;a; p=&amp;b</code> 则 \\(p\\) 指向 \\(\\{a,b\\}\\)。缺口是<strong>约束求解</strong>，不是 TBAA。</p><p>字段敏感 vs 不敏感：结构体字段分开或塌成一块。堆：按分配点（allocation site）抽象对象。</p><h3 id="并查集不是子集" tabindex="-1">并查集不是子集 <a class="header-anchor" href="#并查集不是子集" aria-label="Permalink to &quot;并查集不是子集&quot;">​</a></h3><p>Steensgaard 把 <code>p=q</code> 变成 \\(p\\) 与 \\(q\\) 同类，指向集并在一起，之后无法分开，故更粗。Andersen 的 <code>p=q</code> 是 \\(\\mathrm{pts}(q)\\subseteq\\mathrm{pts}(p)\\)。</p><p><span class="marginnote">Andersen 1994 博士论文。Steensgaard 1996 PLDI。Hind 的综述可对照。本课不写完整 IFDS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建约束。Andersen：迭代或差分解直到不动点。Steensgaard：union-find 加间接边处理 <code>*p</code>。查询：<code>pts(p)∩pts(q)</code> 空则 No alias（对指针值）。</p>',11)),(e(),i(c,null,{default:n(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASN%5B%22%E6%8C%87%E9%92%88%E8%B5%8B%E5%80%BC%22%5D%20--%3E%20AND%5B%22%E5%AD%90%E9%9B%86%E7%BA%A6%E6%9D%9F%20Andersen%22%5D%0A%20%20ASN%20--%3E%20ST%5B%22%E7%AD%89%E5%BC%8F%20Steensgaard%22%5D%0A%20%20AND%20--%3E%20PTS%5B%22%E6%8C%87%E5%90%91%E9%9B%86%22%5D%0A%20%20ST%20--%3E%20PTS%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>与调用：函数指针使调用图与指向分析互相依赖——下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流敏感更精，代价高。上下文敏感（克隆或摘要）减过程间混淆。实用编译器常：Steensgaard 或 Andersen 的限迭代 + TBAA。</p><p>不要把指向集当运行时 GC 的根扫描图；GC 要精确栈图，另一接口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 C++ 虚调用的全部 devirtualize。后课默认：指向分析提供 May 别名。下一课过程间与调用图。</p><p>也不把分析当病毒扫描。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Andersen：子集，较精较慢；Steensgaard：并查，较快较粗。</li><li>分配点抽象堆对象。</li><li>与调用图可联立。</li><li>出处：Andersen, 1994；Steensgaard, 1996。</li></ul>',9))])}const f=r(A,[["render",h]]);export{T as __pageData,f as default};
